/* global Office, Excel, Word, console, FileReader, Image, URL, Blob, atob, Uint8Array, document */

const GEMINI_MODEL = "gemini-3.5-flash-lite";
let HOST_APP = "";
const MAX_RETRY = 3;

// Proxy CORS - thử lần lượt đến khi chèn ảnh URL được
const CORS_PROXIES = [
    (url) => "https://corsproxy.io/?url=" + encodeURIComponent(url),
    (url) => "https://api.allorigins.win/raw?url=" + encodeURIComponent(url),
    (url) => "https://api.codetabs.com/v1/proxy/?quest=" + encodeURIComponent(url),
    (url) => "https://thingproxy.freeboard.io/fetch/" + url,
    (url) => url
];

// Model vẽ ảnh AI - thử lần lượt nếu model trước lỗi
const IMAGE_MODELS = [
    "gemini-2.5-flash-image",
    "gemini-3-pro-image",
    "nano-banana-pro-preview"
];

Office.onReady((info) => {
    if (info.host === Office.HostType.Excel) HOST_APP = "Excel";
    else if (info.host === Office.HostType.Word) {
        HOST_APP = "Word";
        const p = document.getElementById("prompt_input");
        if (p) p.placeholder = "VD: Viết đoạn văn giới thiệu công ty\nVD: Sửa đoạn đang chọn\nVD: Dịch sang tiếng Anh\nVD: Chat: giải thích cho tôi về X";
    }
    document.getElementById("run_button").onclick = executeCommand;
    document.getElementById("clear_button").onclick = clearAll;
    const k = localStorage.getItem("gemini_api_key");
    if (k) document.getElementById("api_key_input").value = k;
    const ms = document.getElementById("model_select");
    if (ms) {
        const sm = localStorage.getItem("gemini_model");
        if (sm) ms.value = sm;
    }
});

function getModel() {
    const ms = document.getElementById("model_select");
    return ms ? ms.value : GEMINI_MODEL;
}
function setStatus(msg, type) {
    const el = document.getElementById("status_area");
    el.className = "status " + type;
    el.innerText = msg;
}

// ====== GỌI GEMINI ======
async function callGemini(apiKey, prompt) {
    const model = getModel();
    const response = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
        {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                contents: [{ parts: [{ text: prompt }] }],
                generationConfig: { temperature: 0.3, maxOutputTokens: 8192, topP: 0.9 }
            })
        }
    );
    const data = await response.json();
    if (!response.ok) throw new Error(data.error?.message || "Lỗi API");
    if (!data.candidates?.length) throw new Error("Không có phản hồi.");
    return data.candidates[0].content.parts.map(p => p.text).join(" ").trim();
}

function cleanCode(code) {
    code = code.replace(/```javascript/gi, "").replace(/```js/gi, "").replace(/```/g, "").trim();
    code = code.replace(/^[\s\S]*?await\s+(Excel|Word)\.run\s*\(\s*async\s*\([^)]*\)\s*=>\s*\{/i, "");
    code = code.replace(/await\s+context\.sync\(\)\s*;?\s*\}\s*\)\s*;?\s*$/i, "");
    return code.trim();
}

function colToLetter(n) {
    let s = ""; n = n + 1;
    while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); }
    return s;
}

// ====== CHUYỂN BLOB ẢNH -> PNG BASE64 (dùng canvas, fix webp/mọi định dạng) ======
function blobToPngBase64(blob) {
    return new Promise((resolve, reject) => {
        const objUrl = URL.createObjectURL(blob);
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
            try {
                const canvas = document.createElement("canvas");
                canvas.width = img.naturalWidth;
                canvas.height = img.naturalHeight;
                const ctx = canvas.getContext("2d");
                ctx.drawImage(img, 0, 0);
                const dataUrl = canvas.toDataURL("image/png");
                URL.revokeObjectURL(objUrl);
                resolve(dataUrl.split(",")[1]);
            } catch (e) {
                URL.revokeObjectURL(objUrl);
                reject(e);
            }
        };
        img.onerror = () => {
            URL.revokeObjectURL(objUrl);
            reject(new Error("Không đọc được ảnh"));
        };
        img.src = objUrl;
    });
}

// ====== CHÈN BASE64 (PNG) VÀO Ô EXCEL ======
async function insertBase64ToCell(base64, targetCell, fitCell) {
    const clean = base64.replace(/\s/g, "");
    await Excel.run(async (context) => {
        const sheet = context.workbook.worksheets.getActiveWorksheet();
        const image = sheet.shapes.addImage(clean);
        image.load("width, height");
        await context.sync();

        const cell = sheet.getRange(targetCell);
        cell.load("left, top, width, height");
        await context.sync();

        image.left = cell.left;
        image.top = cell.top;
        if (fitCell) {
            image.width = cell.width;
            image.height = cell.height;
        } else if (image.width > 350) {
            const ratio = 350 / image.width;
            image.width = 350;
            image.height = image.height * ratio;
        }
        await context.sync();
    });
}

// ====== TẢI ẢNH TỪ URL -> PNG BASE64 (THỬ NHIỀU PROXY + CONVERT PNG) ======
async function urlToBase64(url) {
    let lastErr = "";
    for (let i = 0; i < CORS_PROXIES.length; i++) {
        const proxyUrl = CORS_PROXIES[i](url);
        try {
            setStatus(`🖼️ Đang tải ảnh (nguồn ${i + 1}/${CORS_PROXIES.length})...`, "loading");
            const response = await fetch(proxyUrl, { method: "GET" });
            if (!response.ok) { lastErr = "HTTP " + response.status; continue; }
            const blob = await response.blob();
            if (blob.size < 100) { lastErr = "Ảnh rỗng"; continue; }

            const pngBase64 = await blobToPngBase64(blob);
            if (pngBase64 && pngBase64.length > 100) {
                console.log(`Tải + convert PNG thành công qua proxy ${i + 1}`);
                return pngBase64;
            }
            lastErr = "Convert PNG thất bại";
        } catch (e) {
            lastErr = e.message;
            console.warn(`Proxy ${i + 1} lỗi:`, lastErr);
        }
    }
    throw new Error("Đã thử tất cả nguồn nhưng không tải/chèn được ảnh. Lỗi cuối: " + lastErr);
}

// ====== CHÈN ẢNH TỪ URL ======
async function insertImageFromUrl(imageUrl, targetCell, fitCell) {
    const base64 = await urlToBase64(imageUrl);
    setStatus("📥 Đang chèn ảnh...", "loading");
    await insertBase64ToCell(base64, targetCell, fitCell);
    setStatus(`✅ Đã chèn ảnh vào ô ${targetCell}!`, "success");
}

// ====== VẼ ẢNH BẰNG AI (thử nhiều model, kiểm tra ảnh hợp lệ) ======
async function generateAndInsertImage(apiKey, description, targetCell) {
    let lastErr = "";
    const fullPrompt = "Tạo một hình ảnh: " + description;

    for (let i = 0; i < IMAGE_MODELS.length; i++) {
        const model = IMAGE_MODELS[i];
        try {
            setStatus(`🎨 AI đang vẽ ảnh (model ${i + 1}/${IMAGE_MODELS.length}: ${model})...`, "loading");
            const response = await fetch(
                `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
                {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        contents: [{ role: "user", parts: [{ text: fullPrompt }] }],
                        generationConfig: { responseModalities: ["TEXT", "IMAGE"] }
                    })
                }
            );
            const data = await response.json();
            if (!response.ok) {
                lastErr = data.error?.message || ("HTTP " + response.status);
                console.warn(`Model ${model} lỗi API:`, lastErr);
                continue;
            }

            let base64 = null, mime = "image/png";
            const parts = data.candidates?.[0]?.content?.parts || [];
            for (const part of parts) {
                if (part.inlineData?.data) {
                    base64 = part.inlineData.data;
                    mime = part.inlineData.mimeType || "image/png";
                    break;
                }
            }

            if (!base64) { lastErr = "Model không trả về ảnh"; continue; }
            if (base64.length < 5000) {
                lastErr = "Ảnh trả về quá nhỏ (placeholder rỗng)";
                console.warn(`Model ${model}:`, lastErr, "len=", base64.length);
                continue;
            }

            // Convert sang PNG nếu cần
            let finalBase64 = base64;
            if (!mime.includes("png")) {
                try {
                    const byteStr = atob(base64);
                    const bytes = new Uint8Array(byteStr.length);
                    for (let k = 0; k < byteStr.length; k++) bytes[k] = byteStr.charCodeAt(k);
                    const blob = new Blob([bytes], { type: mime });
                    finalBase64 = await blobToPngBase64(blob);
                } catch (e) {
                    console.warn("Convert PNG lỗi, dùng base64 gốc");
                }
            }

            setStatus("📥 Đang chèn ảnh vào Excel...", "loading");
            await insertBase64ToCell(finalBase64, targetCell, false);
            setStatus(`✅ Đã vẽ và chèn ảnh vào ô ${targetCell}!`, "success");
            return;
        } catch (e) {
            lastErr = e.message;
            console.warn(`Model ${model} lỗi:`, lastErr);
        }
    }
    throw new Error("Không vẽ được ảnh. Có thể API key chưa có quyền tạo ảnh hoặc hết quota. Lỗi cuối: " + lastErr);
}

// ====== PHÂN LOẠI YÊU CẦU: CHAT hay ACTION ======
async function classifyIntent(apiKey, userPrompt) {
    const prompt = `Phân loại yêu cầu sau. CHỈ trả về 1 từ: "CHAT" hoặc "ACTION".
- "ACTION": thao tác trên bảng tính/tài liệu (tính toán, định dạng, lọc, sắp xếp, tô màu, chèn công thức, gộp nhóm, đổi font, viết đoạn văn vào Word). Cần THAY ĐỔI dữ liệu/định dạng.
- "CHAT": trò chuyện, hỏi đáp, tư vấn, giải thích, tìm thông tin, hỏi kiến thức chung.
Ví dụ ACTION: "tính tổng cột A", "tô đỏ ô>100", "lọc trùng", "gộp nhóm".
Ví dụ CHAT: "bạn khỏe không", "giải thích VLOOKUP", "thủ đô Pháp", "tư vấn trồng cây".
Yêu cầu: "${userPrompt}"
Trả về CHAT hoặc ACTION:`;
    const result = await callGemini(apiKey, prompt);
    return result.toUpperCase().includes("ACTION") ? "ACTION" : "CHAT";
}

// ====== XỬ LÝ CHAT ======
async function handleChat(apiKey, userPrompt) {
    const cellMatch = userPrompt.match(/\b(?:vào|ghi vào|điền vào|trả lời vào|ô)\s*([A-Z]{1,3}\d{1,7})\b/i);
    const targetCell = cellMatch ? cellMatch[1].toUpperCase() : null;

    const chatPrompt = `Bạn là trợ lý AI thông minh, thân thiện, trả lời bằng tiếng Việt rõ ràng, hữu ích.
${targetCell ? "LƯU Ý: Trả lời NGẮN GỌN, súc tích vì sẽ ghi vào một ô Excel." : ""}
Câu hỏi/yêu cầu: ${userPrompt}
Trả lời:`;

    const answer = await callGemini(apiKey, chatPrompt);

    if (targetCell && HOST_APP === "Excel") {
        await Excel.run(async (context) => {
            const sheet = context.workbook.worksheets.getActiveWorksheet();
            sheet.getRange(targetCell).values = [[answer]];
            await context.sync();
        });
        setStatus(`✅ Đã trả lời và ghi vào ô ${targetCell}:\n\n${answer}`, "success");
    } else {
        setStatus(`💬 ${answer}`, "success");
    }
}

// ====== BỐI CẢNH EXCEL ======
async function getExcelContext() {
    let info = "";
    await Excel.run(async (ctx) => {
        const sel = ctx.workbook.getSelectedRange();
        sel.load("address, rowCount, columnCount, values, columnIndex, rowIndex");
        const sheet = ctx.workbook.worksheets.getActiveWorksheet();
        sheet.load("name");
        await ctx.sync();

        const isMulti = sel.rowCount > 1 || sel.columnCount > 1;
        const selAddr = sel.address.split("!").pop();
        info += `- Sheet: "${sheet.name}"\n`;

        if (isMulti) {
            info += `\n### ⚠️⚠️ NGƯỜI DÙNG ĐANG BÔI ĐEN VÙNG: ${selAddr}\n`;
            info += `### DỮ LIỆU ĐÃ ĐỌC SẴN VÀO BIẾN "selData". BẮT BUỘC dùng selData. KHÔNG getUsedRange, KHÔNG getSelectedRange để đọc.\n`;
            info += `- Vùng bôi đen: ${sel.rowCount} dòng × ${sel.columnCount} cột\n`;
            info += `- Ánh xạ cột (index → chữ cái cột thật):\n`;
            for (let j = 0; j < sel.columnCount; j++)
                info += `    selData[i][${j}] = cột ${colToLetter(sel.columnIndex + j)}\n`;
            const prev = sel.values.slice(0, 25).map((r, i) => `  selData[${i}] = [${r.join(" | ")}]`).join("\n");
            info += `- Nội dung:\n${prev}\n`;
            if (sel.rowCount > 25) info += `  ...(tổng ${sel.rowCount} dòng)\n`;
        } else {
            info += `- Chọn 1 ô: ${selAddr} (CHƯA bôi đen)\n`;
            const used = sheet.getUsedRangeOrNullObject();
            used.load("address, values, rowCount, columnCount");
            await ctx.sync();
            if (!used.isNullObject) {
                info += `- Vùng có dữ liệu: ${used.address} (${used.rowCount} dòng × ${used.columnCount} cột)\n`;
                const prev = used.values.slice(0, 20).map((r, i) => `  dòng ${i}: [${r.join(" | ")}]`).join("\n");
                info += `- Dữ liệu:\n${prev}\n`;
            }
        }
    });
    return info;
}

async function runExcelCode(code) {
    await Excel.run(async (context) => {
        const sheet = context.workbook.worksheets.getActiveWorksheet();
        const workbook = context.workbook;
        const sel = workbook.getSelectedRange();
        sel.load("values, rowCount, columnCount, address, columnIndex, rowIndex");
        await context.sync();
        const selData = sel.values;
        const selInfo = { address: sel.address, rowCount: sel.rowCount, colCount: sel.columnCount, startCol: sel.columnIndex, startRow: sel.rowIndex };
        const runner = new Function("context", "sheet", "workbook", "Excel", "selData", "selInfo",
            `return (async () => { ${code}\nawait context.sync(); })();`);
        await runner(context, sheet, workbook, Excel, selData, selInfo);
        await context.sync();
    });
}

// ====== BỐI CẢNH WORD ======
async function getWordContext() {
    let info = "";
    await Word.run(async (ctx) => {
        const sel = ctx.document.getSelection();
        sel.load("text");
        await ctx.sync();
        info += `- Văn bản ĐANG CHỌN: "${sel.text || "(chưa chọn gì)"}"\n`;
    });
    return info;
}

async function runWordCode(code) {
    await Word.run(async (context) => {
        const doc = context.document;
        const selection = context.document.getSelection();
        const body = context.document.body;
        const runner = new Function("context", "doc", "selection", "body", "Word",
            `return (async () => { ${code}\nawait context.sync(); })();`);
        await runner(context, doc, selection, body, Word);
        await context.sync();
    });
}

// ====== EXCEL RULES ======
const EXCEL_RULES = `Bạn là chuyên gia Office.js cho Excel, viết code chính xác.

## ĐỊNH DẠNG: CHỈ trả về code JS thuần. KHÔNG markdown, backtick, giải thích.
Code chạy trong: await Excel.run(async (context) => { <CODE> await context.sync(); });
Biến CÓ SẴN: context, sheet, workbook, Excel, selData, selInfo.

## QUY TẮC SỐ 0 (QUAN TRỌNG NHẤT):
- Nếu bối cảnh ghi "ĐANG BÔI ĐEN VÙNG" → BẮT BUỘC dùng biến "selData" (mảng 2 chiều đã đọc sẵn CHỈ dữ liệu vùng bôi đen). selData[i][j]=ô dòng i cột j trong vùng. selData[0]=tiêu đề.
- TUYỆT ĐỐI KHÔNG dùng sheet.getUsedRange() hay getSelectedRange() để đọc khi đã có selData.
- Chỉ dùng getUsedRange khi người dùng CHƯA bôi đen (chọn 1 ô).
- TUYỆT ĐỐI KHÔNG tự bịa ra chuỗi base64 ảnh. KHÔNG chèn ảnh trong luồng này.

## API GHI:
- sheet.getRange("D3").values=[[x]]; hoặc .formulas=[["=..."]];
- Mảng động: sheet.getRange("P33").getResizedRange(n-1,m-1).values=mang;
- Định dạng: dùng workbook.getSelectedRange() rồi .format.font/.fill...
- numberFormat phải là mảng ĐỦ kích thước.

## VÍ DỤ:

# "Tính tổng cột 3 vùng bôi đen điền P33"
let s=0;
for(let i=1;i<selData.length;i++){const v=selData[i][3];s+=(typeof v==="number"?v:(parseFloat(v)||0));}
sheet.getRange("P33").values=[[s]];

# "Lọc giá trị không trùng cột 0 vùng bôi đen sang cột F"
const arr=[];
for(let i=1;i<selData.length;i++){const v=selData[i][0];if(v!==""&&v!==null)arr.push(v);}
const u=[...new Set(arr)].map(v=>[v]);
if(u.length>0)sheet.getRange("F1").getResizedRange(u.length-1,0).values=u;

# "PIVOT: gộp nhóm vùng bôi đen theo cột 0,1,2 tính tổng cột 3 điền từ P33"
const map={},order=[];
for(let i=1;i<selData.length;i++){
  const g0=selData[i][0],g1=selData[i][1],g2=selData[i][2],raw=selData[i][3];
  if((g0===""||g0===null)&&(g1===""||g1===null))continue;
  const val=typeof raw==="number"?raw:(parseFloat(raw)||0);
  const key=String(g0)+"|||"+String(g1)+"|||"+String(g2);
  if(map[key]===undefined){map[key]={g0,g1,g2,sum:0};order.push(key);}
  map[key].sum+=val;
}
const result=order.map(k=>[map[k].g0,map[k].g1,map[k].g2,map[k].sum]);
if(result.length>0)sheet.getRange("P33").getResizedRange(result.length-1,3).values=result;

# "Đổi font vùng bôi đen thành Times New Roman cỡ 13 in đậm"
const r=workbook.getSelectedRange();
r.format.font.name="Times New Roman";r.format.font.size=13;r.format.font.bold=true;

# "Đếm số lần xuất hiện cột 0 vùng bôi đen, ghi cột H,I"
const c={},o=[];
for(let i=1;i<selData.length;i++){const v=selData[i][0];if(v===""||v===null)continue;const k=String(v);if(c[k]===undefined){c[k]=0;o.push(k);}c[k]++;}
const ro=o.map(k=>[k,c[k]]);
if(ro.length>0)sheet.getRange("H1").getResizedRange(ro.length-1,1).values=ro;

## QUY TẮC VÀNG:
1. ĐÃ bôi đen → dùng selData đọc, dùng getSelectedRange chỉ để FORMAT.
2. selData[0]=tiêu đề, dữ liệu từ selData[1].
3. numberFormat mảng đủ kích thước. Ngày text phải parse thành số ngày Excel = Math.floor((new Date(y,m-1,d)-new Date(1899,11,30))/86400000).
4. Ghi mảng động: getResizedRange(n-1,m-1). Bỏ qua dòng rỗng khi nhóm/lọc/đếm.
5. Số dạng text dùng parseFloat().
6. KHÔNG bao giờ tự bịa base64 ảnh.`;

