// ====== HÀM CHÍNH ======
async function executeCommand() {
    const apiKey = document.getElementById("api_key_input").value.trim();
    const userPrompt = document.getElementById("prompt_input").value.trim();
    const btn = document.getElementById("run_button");

    if (!apiKey) { setStatus("⚠️ Nhập API key.", "error"); return; }
    if (!userPrompt) { setStatus("⚠️ Nhập yêu cầu.", "error"); return; }

    localStorage.setItem("gemini_api_key", apiKey);
    const ms = document.getElementById("model_select");
    if (ms) localStorage.setItem("gemini_model", ms.value);
    btn.disabled = true;

    try {
        // ====== KIỂM TRA LỆNH LIÊN QUAN ẢNH (ưu tiên cao nhất) ======
        if (HOST_APP === "Excel") {
            const urlMatch = userPrompt.match(/https?:\/\/[^\s"']+/i);
            const isImageCmd = /ảnh|hình|image|picture/i.test(userPrompt);

            if (isImageCmd) {
                const cellMatch = userPrompt.match(/\b(?:vào|tại|ô)\s*([A-Z]{1,3}\d{1,7})\b/i);
                const targetCell = cellMatch ? cellMatch[1].toUpperCase() : "A1";

                // Có URL -> chèn ảnh thật từ URL
                if (urlMatch) {
                    const fitCell = /vừa ô|khít ô|vừa khít|fit/i.test(userPrompt);
                    await insertImageFromUrl(urlMatch[0], targetCell, fitCell);
                    btn.disabled = false;
                    return;
                }

                // KHÔNG có URL -> LUÔN dùng AI vẽ ảnh
                let desc = userPrompt
                    .replace(/chèn|thêm|vẽ|tạo|sinh|generate|banana|bằng ai|bằng banana/gi, "")
                    .replace(/\bảnh\b|\bhình\b|image|picture/gi, "")
                    .replace(/\b(?:vào|tại|ô)\s*[A-Z]{1,3}\d{1,7}\b/gi, "")
                    .trim();
                if (!desc) desc = userPrompt;
                setStatus("🎨 Không có link ảnh → AI sẽ tự VẼ theo mô tả...", "loading");
                await generateAndInsertImage(apiKey, desc, targetCell);
                btn.disabled = false;
                return;
            }
        }

        // ====== PHÂN LOẠI: CHAT hay ACTION ======
        setStatus("🧠 Đang hiểu yêu cầu...", "loading");
        const intent = await classifyIntent(apiKey, userPrompt);
        console.log("Phân loại:", intent);

        if (intent === "CHAT") {
            setStatus("💬 Đang trả lời...", "loading");
            await handleChat(apiKey, userPrompt);
            btn.disabled = false;
            return;
        }

        // ====== ACTION: viết code + thực thi ======
        let contextInfo, rules, runFunc;
        if (HOST_APP === "Excel") {
            contextInfo = await getExcelContext();
            rules = EXCEL_RULES;
            runFunc = runExcelCode;
        } else {
            contextInfo = await getWordContext();
            rules = WORD_RULES;
            runFunc = runWordCode;
        }

        let lastError = "", code = "";
        for (let attempt = 1; attempt <= MAX_RETRY; attempt++) {
            setStatus(attempt === 1 ? "⚙️ Đang xử lý..." : `🔄 Đang thử lại (${attempt}/${MAX_RETRY})...`, "loading");
            let prompt = attempt === 1
                ? `${rules}\n\n## BỐI CẢNH:\n${contextInfo}\n\n## YÊU CẦU:\n${userPrompt}\n\nViết code (dùng selData nếu đã bôi đen vùng):`
                : `${rules}\n\n## BỐI CẢNH:\n${contextInfo}\n\n## YÊU CẦU:\n${userPrompt}\n\n## CODE LỖI:\n${code}\n\n## LỖI:\n${lastError}\n\nViết lại code ĐÚNG:`;

            code = cleanCode(await callGemini(apiKey, prompt));
            console.log(`=== Lần ${attempt} - Code (${HOST_APP}) ===\n${code}\n===`);

            try {
                await runFunc(code);
                setStatus(attempt === 1 ? "✅ Thành công!" : `✅ Thành công (sau ${attempt} lần)!`, "success");
                btn.disabled = false;
                return;
            } catch (e) {
                lastError = e.message;
                console.warn(`Lần ${attempt} lỗi:`, lastError);
                if (attempt === MAX_RETRY) throw new Error(`Thử ${MAX_RETRY} lần vẫn lỗi: ${lastError}`);
            }
        }
    } catch (error) {
        console.error(error);
        setStatus("❌ " + error.message, "error");
    } finally {
        btn.disabled = false;
    }
}

function clearAll() {
    document.getElementById("prompt_input").value = "";
    document.getElementById("status_area").className = "status";
    document.getElementById("status_area").innerText = "";
}